import { escHTML } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs } from "../_utils/component.helper";

/**
 * Topic Listing DXP Component -- Server-Side Renderer
 *
 * Resolves one topic page and a list of other pages/documents via
 * info.fns.resolveUri, mirroring this project's `card`/`image-gallery`
 * resolution architecture -- best-effort per source, never throws. See
 * topic-listing.spec.md assumptions 1-2 for exactly what's confirmed vs
 * inferred about the Matrix asset schema this relies on.
 */

const FILE_ICONS = {
  pdf: "fa-file-pdf",
  doc: "fa-file-word",
  docx: "fa-file-word",
  ppt: "fa-file-powerpoint",
  pptx: "fa-file-powerpoint",
  xls: "fa-file-excel",
  xlsx: "fa-file-excel",
};
const DEFAULT_FILE_ICON = "fa-file";

/**
 * CONTENT_API_URL -- a Matrix REST resource acting as an authenticated
 * Content API proxy, confirmed working via the `content-api-picker` debug
 * component, and reused directly by `image-gallery`/`card`/`document`. Read
 * from info.env at call time, not editor-configurable.
 */
const ROOT_ID_PARAM_NAME = "rootId";

function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? (value[0] || "") : "";
}

/**
 * Maps a resolved topic page onto {title, description, href} --
 * name/url/metadata.page-description -- see topic-listing.spec.md
 * assumption 1.
 */
function toTopic(page) {
  if (!page) return null;
  const metadata = page.metadata || {};
  return {
    title: page.name || "",
    description: firstMetadataValue(metadata, "page-description"),
    href: page.url || "",
  };
}

/**
 * Combines the resolved topic asset (if any) with a free-text name
 * override -- `topicName` wins as the heading whenever it's non-blank,
 * description/button still come from the resolved asset either way. If
 * there's no override AND no resolved asset (topicSource unset, blank, or
 * unresolvable), there is no topic to render at all -- returns null rather
 * than a title-less block. See topic-listing.spec.md assumption 3.
 */
function buildTopic(resolvedTopic, topicNameOverride) {
  const title = String(topicNameOverride ?? "").trim() || resolvedTopic?.title || "";
  if (!title) return null;
  return {
    title,
    description: resolvedTopic?.description || "",
    href: resolvedTopic?.href || "",
  };
}

/** Raw byte count -> "182 KB" (rounded, no decimal, matching the source screenshot). */
function formatFileSize(bytes) {
  const value = Number(bytes);
  if (!Number.isFinite(value) || value <= 0) return "";
  return `${Math.round(value / 1024)} KB`;
}

function fileIconClass(fileType) {
  const key = String(fileType ?? "").toLowerCase();
  return FILE_ICONS[key] || DEFAULT_FILE_ICON;
}

/**
 * Maps one resolved asset onto the item shape for the given listMode --
 * "document" (file icon/format/size), "topics" (title + description via
 * metadata.page-description, same field/shape as the main topic --
 * assumption 1), or "links" (title only, bulleted). listMode is an
 * explicit editor choice (added 0.2.1), applied uniformly to every
 * linkSources entry -- see topic-listing.spec.md assumption 2.
 */
function toItem(asset, listMode) {
  if (!asset) return null;
  const name = asset.name || "";
  const href = asset.url || "";
  if (!name) return null;

  if (listMode === "document") {
    const fileType = asset.file_type || "";
    const size = formatFileSize(asset.file_size);
    const meta = [fileType.toUpperCase(), size].filter(Boolean).join(" | ");
    return { kind: "document", title: name, href, fileType, meta, iconClass: fileIconClass(fileType) };
  }

  if (listMode === "topics") {
    const description = firstMetadataValue(asset.metadata, "page-description");
    return { kind: "child", title: name, href, description };
  }

  return { kind: "link", title: name, href };
}

/**
 * Resolves one matrix-asset-uri via fns.resolveUri. The result is an
 * `{ ok, data }` envelope in Storybook mocks but the bare asset on a live
 * page (see card.spec.md assumption 4), so both are accepted; checking the
 * `data` key's presence, not truthiness, keeps a `{ data: null }` "not
 * found" envelope from being read as an asset. Best effort: any failure
 * yields null rather than throwing.
 */
async function resolveAsset(uri, fns) {
  if (!uri) return null;
  try {
    const res = await fns?.resolveUri?.(uri);
    return res && "data" in res ? res.data : (res ?? null);
  } catch {
    return null;
  }
}

async function resolveTopic(topicSource, fns) {
  return toTopic(await resolveAsset(topicSource, fns));
}

async function resolveItems(linkSources, fns, listMode) {
  const sources = Array.isArray(linkSources) ? linkSources : [];
  const items = await Promise.all(
    sources.map(async (uri) => toItem(await resolveAsset(uri, fns), listMode)),
  );
  return items.filter(Boolean);
}

/**
 * Combines individually-picked `linkSources` with every child of the picked
 * `parentAsset`, de-duplicated by uri in case the same asset is reachable
 * both ways. Same mechanism as `card`/`document`'s own `resolveCombinedAssets`.
 */
async function resolveCombinedLinkSources(linkSources, parentAsset, contentApiUrl) {
  const children = await resolveParentChildUris(parentAsset, contentApiUrl);
  const sources = Array.isArray(linkSources) ? linkSources : [];
  return [...new Set([...sources, ...children])];
}

/**
 * Resolves `parentAsset`'s children into matrix-asset-uri strings, via a
 * plain unauthenticated fetch() against CONTENT_API_URL -- not info.fns,
 * which has no children-listing capability at all on this tenant. Only each
 * child's `id` is used to rebuild a matrix-asset-uri (reusing parentAsset's
 * own domain); the listing's own metadata is deliberately not relied on, so
 * every child still resolves through the exact same
 * fns.resolveUri()/toItem() path as an individually-picked asset. See
 * topic-listing.spec.md assumption 4.
 */
async function resolveParentChildUris(parentAsset, contentApiUrl) {
  const { domain, id: parentId } = parseAssetUri(parentAsset);
  if (!domain || !parentId || !contentApiUrl) return [];

  const url = `${contentApiUrl}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(parentId)}`;

  let body;
  try {
    const res = await fetch(url);
    if (!res.ok) return [];
    body = await res.json();
  } catch {
    return [];
  }

  if (!Array.isArray(body)) return [];
  return body
    .map((item) => item?.id)
    .filter(Boolean)
    .map((id) => `matrix-asset://${domain}/${id}`);
}

function parseAssetUri(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/(\d+)(?::.+)?$/.exec(String(uri ?? ""));
  return { domain: match?.[1] ?? null, id: match?.[2] ?? null };
}

function renderTopic(topic, visibility) {
  if (!topic) return "";
  const descriptionHtml = visibility.showDescription && topic.description
    ? `<p class="topic-listing__description">${escHTML(topic.description)}</p>`
    : "";
  const buttonHtml = visibility.showActionLink && topic.href
    ? `<a href="${escHTML(topic.href)}" class="button button-secondary topic-listing__button">Find out more</a>`
    : "";

  return `
      <div class="topic-listing__topic">
        <h2 class="topic-listing__title">${escHTML(topic.title)}</h2>
        ${descriptionHtml}
        ${buttonHtml}
      </div>`;
}

function renderLinkItem(item) {
  return `
        <li class="topic-listing__item topic-listing__item--link">
          <span class="topic-listing__bullet" aria-hidden="true"></span>
          <a href="${escHTML(item.href)}" class="topic-listing__link">${escHTML(item.title)}</a>
        </li>`;
}

function renderChildItem(item, visibility) {
  const descriptionHtml = visibility.showItemDescription && item.description
    ? `<p class="topic-listing__child-description">${escHTML(item.description)}</p>`
    : "";

  return `
        <li class="topic-listing__item topic-listing__item--child">
          <a href="${escHTML(item.href)}" class="topic-listing__child-title">${escHTML(item.title)}</a>
          ${descriptionHtml}
        </li>`;
}

function renderDocumentItem(item) {
  return `
        <li class="topic-listing__item topic-listing__item--document">
          <i class="fa-thin ${item.iconClass} topic-listing__doc-icon" aria-hidden="true"></i>
          <div class="topic-listing__doc-body">
            <a href="${escHTML(item.href)}" class="topic-listing__doc-title">${escHTML(item.title)}</a>
            ${item.meta ? `<span class="topic-listing__doc-meta">${escHTML(item.meta)}</span>` : ""}
          </div>
        </li>`;
}

const ITEM_RENDERERS = {
  document: renderDocumentItem,
  child: renderChildItem,
  link: renderLinkItem,
};

function renderItems(items, visibility) {
  if (!items || items.length === 0) return "";
  const itemsHtml = items
    .map((item) => ITEM_RENDERERS[item.kind](item, visibility))
    .join("\n");

  return `

      <ul class="topic-listing__items">${itemsHtml}
      </ul>`;
}

export default {
  async main(input, info) {
    const {
      listMode = "Links",
      topicSource = "",
      topicName = "",
      linkSources = [],
      parentAsset = "",
      visibilityOptions = {},
    } = input || {};
    const {
      showDescription = true,
      showActionLink = true,
      showItemDescription = true,
    } = visibilityOptions;
    const visibility = { showDescription, showActionLink, showItemDescription };
    const fns = info?.fns;

    /**
     * Manifest enum values are capitalised for the DXP editor dropdown
     * (Topics/Links/Document) -- normalise to lowercase here to match
     * toItem()'s lowercase mode checks. Unrecognised values fall back to
     * "links", the same graceful-default pattern as card's cardMode and
     * in-page-alert's alertType.
     */
    const normalizedMode = ["topics", "links", "document"].includes(String(listMode).toLowerCase())
      ? String(listMode).toLowerCase()
      : "links";

    const combinedLinkSources = await resolveCombinedLinkSources(
      linkSources,
      parentAsset,
      info?.env?.CONTENT_API_URL,
    );

    const [resolvedTopic, items] = await Promise.all([
      resolveTopic(topicSource, fns),
      resolveItems(combinedLinkSources, fns, normalizedMode),
    ]);

    const topic = buildTopic(resolvedTopic, topicName);
    if (!topic && items.length === 0) return "";

    return /*html*/`
<div ${componentAttrs("topic-listing", input)}>
  <div class="topic-listing__container">
    <div class="topic-listing__content">${renderTopic(topic, visibility)}${renderItems(items, visibility)}
    </div>
  </div>
</div>
`;
  },
};
