/**
 * `topicSource` is optional -- with none set, the topic block is omitted
 * entirely (no title/description/button) and only the items list renders,
 * spanning the full width via the `:only-child` CSS rule.
 */
const noTopicArgs = {
  listMode: 'Links',
  linkSources: [
    'matrix-asset://ntg/5101',
    'matrix-asset://ntg/5102',
  ],
};
const noTopicHtml = await squiz.markup(noTopicArgs, mockInfo);

export const NoTopic = {
  render: () => squiz(noTopicArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'No `topicSource` and no `topicName` -- the topic block is omitted entirely, and the items list spans the full width instead of sitting in the narrow left column.' },
      source: { code: noTopicHtml, language: 'html', type: 'code' },
    },
  },
};

/**
 * `topicName` overrides the heading text even though `topicSource` is also
 * set and resolves -- description/button still come from the resolved
 * topic asset, only the title text changes.
 */
const customTopicNameArgs = {
  listMode: 'Links',
  topicSource: 'matrix-asset://ntg/5001',
  topicName: 'A Custom Heading, Not the Page Name',
  linkSources: [
    'matrix-asset://ntg/5101',
    'matrix-asset://ntg/5102',
  ],
};
const customTopicNameHtml = await squiz.markup(customTopicNameArgs, mockInfo);

export const CustomTopicName = {
  render: () => squiz(customTopicNameArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: '`topicName` overrides the heading text even though `topicSource` (matrix-asset://ntg/5001, named "Topic title") also resolves -- description and button still come from the resolved asset, only the title text changes.' },
      source: { code: customTopicNameHtml, language: 'html', type: 'code' },
    },
  },
};

/**
 * `visibilityOptions` hides the topic description and "Find out more"
 * button, and hides item descriptions in Topics mode -- same collapsible
 * boolean-group pattern as `card`'s own `visibilityOptions`.
 */
const hiddenElementsArgs = {
  listMode: 'Topics',
  topicSource: 'matrix-asset://ntg/5001',
  linkSources: [
    'matrix-asset://ntg/5301',
    'matrix-asset://ntg/5302',
  ],
  visibilityOptions: {
    showDescription: false,
    showActionLink: false,
    showItemDescription: false,
  },
};
const hiddenElementsHtml = await squiz.markup(hiddenElementsArgs, mockInfo);

export const HiddenElements = {
  render: () => squiz(hiddenElementsArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: '`visibilityOptions.showDescription`/`showActionLink`/`showItemDescription` all set to `false` -- the topic renders as a bare heading, and each Topics-mode item renders as title only, no description.' },
      source: { code: hiddenElementsHtml, language: 'html', type: 'code' },
    },
  },
};
